package org.springframework.samples.petclinic.model;

import org.springframework.core.style.ToStringCreator;
import org.springframework.samples.petclinic.util.E164Telephone;
import org.springframework.samples.petclinic.util.Sha256Hex;
import org.springframework.samples.petclinic.util.Soundex;

import jakarta.persistence.*;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Pattern;

import java.time.LocalDate;
import java.time.Period;
import java.util.*;

/**
 * Simple JavaBean domain object representing an owner.
 *
 * @author Ken Krebs
 * @author Juergen Hoeller
 * @author Sam Brannen
 * @author Michael Isvy
 */
@Entity
@Table(name = "owners")
public class Owner extends Person {

    @Column(name = "title")
    private String title;

    @Column(name = "address")
    @NotEmpty
    private String address;

    @Column(name = "address_line1")
    private String addressLine1;

    @Column(name = "address_line2")
    private String addressLine2;

    @Column(name = "city")
    @NotEmpty
    private String city;

    @Column(name = "telephone")
    @NotEmpty
    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a leading '+' and 8 to 15 digits)")
    private String telephone;

    @Column(name = "email")
    @Email
    private String email;

    @Column(name = "registration_date")
    private LocalDate registrationDate;

    @Column(name = "birth_date")
    private LocalDate birthDate;

    @Column(name = "member_id")
    private String memberId;

    @Column(name = "household_id")
    private String householdId;

    @Column(name = "namesake_count")
    private Integer namesakeCount;

    @Column(name = "postcode")
    private String postcode;

    /**
     * Whether this owner was flagged as a suspected soft-duplicate of an existing owner. Set
     * {@code true} at create time when the owner's {@link #getIdentityKey() identity key} differs
     * from every existing owner's (so it is not a hard 409 duplicate) yet it shares an existing,
     * non-deleted owner's {@code soundex(lastName)} and {@code postcode}. The matched owner is
     * recorded in {@link #getPossibleDuplicateOf()}.
     */
    @Column(name = "possible_duplicate")
    private boolean possibleDuplicate;

    /**
     * The id of the existing owner this owner soft-matches, set together with
     * {@link #isPossibleDuplicate()} when a soft match is detected; {@code null} otherwise.
     */
    @Column(name = "possible_duplicate_of")
    private Integer possibleDuplicateOf;

    /**
     * Whether this owner has been soft-deleted. A newly created owner is {@code false}; deleting an
     * owner (DELETE /api/owners/{id}) flags this {@code true} and retains the row instead of removing
     * it. Deleted owners are ignored by the create endpoint's duplicate and identity checks.
     */
    @Column(name = "deleted")
    private boolean deleted;

    /**
     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}, captured
     * when the owner was created: a new owner's level may not exceed one above the highest level
     * among the household members that already existed at creation time. {@code null} when no cap
     * applies (the owner belonged to no existing household member when created), in which case the
     * membership level is returned uncapped.
     */
    @Column(name = "membership_level_cap")
    private Integer membershipLevelCap;

    /**
     * Write-only, non-persistent acknowledgement that this owner deliberately shares a household
     * with an existing owner. Retained as part of the API contract but now inert: an owner sharing
     * an existing owner's {@code lastName} and {@code postcode} is always admitted as a household
     * member (its membership level capped by {@link #getMembershipLevelCap()}), so the former
     * household-duplicate rejection this flag used to bypass no longer exists.
     */
    @Transient
    private boolean sharesHousehold;

    /**
     * Read-only, non-persistent count of the owners that share this owner's {@code householdId}
     * (including this owner), populated by the service when an owner is loaded for presentation.
     * Zero when the owner belongs to no household. Used to derive the membership tier.
     */
    @Transient
    private int householdSize;

    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
    private Set<Pet> pets;

