    /** The household size at or above which an owner earns the household membership points. */
    public static final int MEMBERSHIP_HOUSEHOLD_SIZE = 3;

    /** The month (1 July) on which the fiscal year begins. */
    public static final int FISCAL_YEAR_START_MONTH = 7;

    /**
     * The number of elapsed fiscal years at or above which an owner earns the tenure membership
     * points.
     */
    public static final long MEMBERSHIP_TENURE_FISCAL_YEARS = 1;

    /**
     * The fiscal year (as a full four-digit number) that {@code date} falls in, where the fiscal
     * year begins on 1 July and is labelled by the calendar year in which it ends: a date on or
     * after 1 July belongs to the next calendar year's fiscal year.
     */
    public static int fiscalYearOf(LocalDate date) {
        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
    }

    /**
     * The fiscal year carried by the owner's {@link #getMemberId() memberId}, formatted
     * {@code 'FY<YY>'} where YY is the two-digit fiscal-year (FY) segment of the memberId — the two
     * characters following the {@link Region#IDENTITY_VERSION_TAG V2} version tag and the
     * {@code <REGION>} prefix (see {@link Region#regionOfMemberId(String)}). Null when no memberId
     * has been assigned.
     */
    public String getFiscalYear() {
        if (this.memberId == null) {
            return null;
        }
        int tagLength = this.memberId.startsWith(Region.IDENTITY_VERSION_TAG)
            ? Region.IDENTITY_VERSION_TAG.length() : 0;
        int start = tagLength + Region.regionOfMemberId(this.memberId).length();
        if (this.memberId.length() < start + 2) {
            return null;
        }
        return "FY" + this.memberId.substring(start, start + 2);
    }

    /**
     * The owner's membership points, computed from stored fields: they start at 0, gain 2 when an
     * email is present, gain 1 when {@code namesakeCount} is 0, gain 2 for a household of
     * {@value #MEMBERSHIP_HOUSEHOLD_SIZE} or more (see {@link #getHouseholdSize()}), and gain 3 when
     * the owner's tenure (fiscal years elapsed since its {@code registrationDate}) is at least
     * {@value #MEMBERSHIP_TENURE_FISCAL_YEARS}.
     */
    public int getMembershipPoints() {
        int points = 0;
        if (this.email != null && !this.email.isEmpty()) {
            points += 2;
        }
        if (this.namesakeCount != null && this.namesakeCount == 0) {
            points += 1;
        }
        if (this.householdSize >= MEMBERSHIP_HOUSEHOLD_SIZE) {
            points += 2;
        }
        if (this.registrationDate != null
                && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate))
                        >= MEMBERSHIP_TENURE_FISCAL_YEARS) {
            points += 3;
        }
        return points;
    }

    /**
     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()}: 1 for 0-1
     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points, then capped by the
     * {@link #getMembershipLevelCap() membership level cap} when one was captured at creation time.
     */
    public int getMembershipLevel() {
        int level = computeMembershipLevel();
        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
            return this.membershipLevelCap;
        }
        return level;
    }

    /**
     * The uncapped membership level derived purely from {@link #getMembershipPoints()}: 1 for 0-1
     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
     */
    private int computeMembershipLevel() {
        int points = getMembershipPoints();
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return 1;
    }

    /**
     * The owner's marketing segment formatted {@code '<TIER>_<AREA>'}, one of
     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when {@link #getMembershipLevel()} is 3
     * or more, otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's locality (the
     * region of its {@code memberId}, see {@link Region#regionOfMemberId(String)}) is a known
     * region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}.
     */
    public String getOwnerSegment() {
        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
        String area = Region.isKnownRegion(Region.regionOfMemberId(this.memberId))
                ? "METRO" : "REGIONAL";
        return tier + "_" + area;
    }

    public Integer getMembershipLevelCap() {
